import sys
import os
import re
import json
from pathlib import Path

def evaluate_expression(expr):
    expr = expr.strip()
    if not expr:
        return 0
    try:
        # Use eval with a restricted namespace to prevent arbitrary code execution
        # We'll parse the expression manually to avoid security risks
        # This is a simplified parser for the given problem constraints
        tokens = re.findall(r'(\d+|[-+*/()])', expr)
        stack = []
        precedence = {'*': 2, '/': 2, '+': 1, '-': 1}
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                stack.append(int(token))
            elif token in precedence:
                while (stack and isinstance(stack[-1], str) and
                       precedence[stack[-1]] >= precedence[token]):
                    b = stack.pop()
                    a = stack.pop()
                    if token == '+':
                        stack.append(a + b)
                    elif token == '-':
                        stack.append(a - b)
                    elif token == '*':
                        stack.append(a * b)
                    elif token == '/':
                        stack.append(a // b)
                stack.append(token)
            i += 1
        while stack and isinstance(stack[-1], str):
            b = stack.pop()
            a = stack.pop()
            if b == '+':
                stack.append(a + b)
            elif b == '-':
                stack.append(a - b)
            elif b == '*':
                stack.append(a * b)
            elif b == '/':
                stack.append(a // b)
        return stack[0] if stack else 0
    except:
        return 0

def parse_cache(cache_path):
    if not os.path.exists(cache_path):
        return {}
    try:
        with open(cache_path, 'r') as f:
            return json.load(f)
    except:
        return {}

def write_cache(cache_path, cache_data):
    with open(cache_path, 'w') as f:
        json.dump(cache_data, f)

def process_xml(input_path, output_path):
    input_file = Path(input_path)
    cache_path = input_file.with_name(f"{input_file.stem}.expandcache")
    cache = parse_cache(cache_path)
    replaced = 0
    reused = 0

    with open(input_path, 'r') as f:
        content = f.read()

    def replace_placeholders(match):
        nonlocal replaced, reused
        expr = match.group(1).strip()
        if expr in cache:
            replaced += 1
            reused += 1
            return str(cache[expr])
        else:
            replaced += 1
            result = evaluate_expression(expr)
            cache[expr] = result
            write_cache(cache_path, cache)
            return str(result)

    pattern = re.compile(r'\{\{(\s*[^}]*)\}\}')
    processed = pattern.sub(replace_placeholders, content)

    with open(output_path, 'w') as f:
        f.write(processed)

    print(f"Replaced {replaced} placeholders ({reused} from cache).")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python expand.py <input.xml> <output.xml>")
        sys.exit(1)
