def process_xml(input_path, output_path):
    input_file = Path(input_path)
    cache_path = input_file.with_name(f"{input_file.stem}.expandcache")

    cache = {}
    reused = 0
    total_placeholders = 0

    # Load cache if exists
    if cache_path.exists():
        with open(cache_path, 'r') as f:
            for line in f:
                expr, result = line.strip().split(maxsplit=1)
                cache[expr] = int(result)

    def get_result(expr):
        nonlocal reused
        expr = expr.strip()
        if expr in cache:
            reused += 1
            return cache[expr]
        try:
            result = evaluate_expression(expr)
            cache[expr] = result
            return result
        except ValueError as e:
            raise ValueError(f"Failed to evaluate expression '{expr}': {e}")

    # Parse XML
    tree = ET.parse(input_path)
    root = tree.getroot()

    def replace_placeholders(element):
        nonlocal total_placeholders
        for child in list(element):
            if child.tag == '{{':
                # Handle attribute placeholders
                attr_name = child.attrib.get('{{', None)
                if attr_name:
                    expr = child.attrib.get('}}', None)
                    if expr:
                        try:
                            value = get_result(expr)
                            child.attrib['{{' + attr_name + '}}'] = str(value)
                            total_placeholders += 1
                        except ValueError as e:
                            print(f"Error processing attribute placeholder: {e}", file=sys.stderr)
                continue

            # Handle text content placeholders
            for text in child.itertext():
                if text.startswith('{{') and text.endswith('}}'):
                    expr = text[2:-2]
                    try:
                        value = get_result(expr)
                        child.text = str(value)
                        total_placeholders += 1
                    except ValueError as e:
                        print(f"Error processing text placeholder: {e}", file=sys.stderr)

            # Recursively process children
            replace_placeholders(child)

    replace_placeholders(root)

    # Save cache
    with open(cache_path, 'w') as f:
        for expr, result in cache.items():
            f.write(f"{expr} {result}\n")

    # Write output
    tree.write(output_path, encoding='utf-8', xml_declaration=True)

    print(f"Replaced {total_placeholders} placeholders ({reused} from cache).")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python expand.py <input.xml> <output.xml>", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]

    process_xml(input_path, output_path)

