import sys
import xml.etree.ElementTree as ET
from pathlib import Path
import os

def evaluate_expression(expr):
    expr = expr.strip()
    if not expr:
        return 0
    try:
        return int(eval(expr))
    except:
        return 0

def process_xml(input_path, output_path):
    cache = {}
    cache_path = input_path.with_suffix('.expandcache')

    if cache_path.exists():
        with open(cache_path, 'r') as f:
            cache = eval(f.read())

    placeholder_count = 0
    cache_used = 0

    tree = ET.parse(input_path)
    root = tree.getroot()

    def replace_placeholders(element):
        nonlocal placeholder_count, cache_used
        for child in list(element):
            if child.tag.endswith('{expr}'):
                placeholder_count += 1
                expr = child.text.strip()
                if expr:
                    if expr in cache:
                        cache_used += 1
                        child.text = str(cache[expr])
                    else:
                        value = evaluate_expression(expr)
                        cache[expr] = value
                        child.text = str(value)
        for child in list(element):
            replace_placeholders(child)

    replace_placeholders(root)
    tree.write(output_path)

    with open(cache_path, 'w') as f:
        f.write(str(cache))

    print(f"Replaced {placeholder_count} placeholders ({cache_used} from cache).")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python expand.py <input_xml> <output_xml>")
        sys.exit(1)

    input_path = Path(sys.argv[1])
    output_path = Path(sys.argv[2])

    if not input_path.exists():
        print(f"Error: Input file {input_path} does not exist.")
        sys.exit(1)

    process_xml(input_path, output_path)
